/**
 * @name Path traversal in file operations
 * @description File operations with unsanitized user input can lead to path traversal attacks
 * @kind path-problem
 * @problem.severity error
 * @id py/path-traversal-pytz
 * @tags security
 *        external/cwe/cwe-022
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.Concepts
import semmle.python.ApiGraphs

module PathTraversalConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    // Parameters to functions that might receive user input
    source instanceof DataFlow::ParameterNode or
    // Function arguments
    exists(DataFlow::CallCfgNode call |
      source = call.getArg(_)
    )
  }

  predicate isSink(DataFlow::Node sink) {
    // File system access operations
    sink = any(FileSystemAccess fa).getAPathArgument()
  }

  predicate isBarrier(DataFlow::Node node) {
    // Path sanitization or validation
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("os").getMember("path").getMember(["abspath", "realpath", "normpath"]).getACall() and
      node = call
    )
  }
}

module PathTraversalFlow = TaintTracking::Global<PathTraversalConfig>;
import PathTraversalFlow::PathGraph

from PathTraversalFlow::PathNode source, PathTraversalFlow::PathNode sink
where PathTraversalFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Potential path traversal from $@.", source.getNode(), "user-controlled input"

/**
 * @name Timezone name path traversal vulnerability
 * @description User-controlled timezone names used in file path construction without proper validation
 * @kind path-problem
 * @problem.severity error
 * @id py/pytz-timezone-path-traversal
 * @tags security
 *        external/cwe/cwe-022
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs

module TimezonePathTraversalConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    // Function parameters that accept timezone names
    exists(Function f, Parameter p |
      (f.getName() in ["timezone", "_tzinfo_factory", "build_tzinfo", "_p"] and
       source.(DataFlow::ParameterNode).getParameter() = p and
       p = f.getAnArg())
    )
  }

  predicate isSink(DataFlow::Node sink) {
    // File operations with path arguments
    exists(DataFlow::CallCfgNode call |
      (
        call = API::builtin("open").getACall() or
        call = API::moduleImport("os").getMember("path").getMember("join").getACall() or
        call = API::moduleImport("pkg_resources").getMember("resource_stream").getACall()
      ) and
      sink = call.getArg(_)
    )
  }
}

module TimezonePathTraversalFlow = TaintTracking::Global<TimezonePathTraversalConfig>;
import TimezonePathTraversalFlow::PathGraph

from TimezonePathTraversalFlow::PathNode source, TimezonePathTraversalFlow::PathNode sink
where TimezonePathTraversalFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Potential path traversal via timezone name from $@.", source.getNode(), "user input"
